const respuesta = $('Message a model').first().json;

const textoIA = respuesta.output[0].content[0].text;

const datos = JSON.parse(textoIA);

const nombreValido =
  typeof datos.nombre_contacto === 'string' &&
  datos.nombre_contacto.trim().length > 0;

datos.requiere_revision = !nombreValido;

return [
  {
    json: datos
  }
];

